package org.matheclipse.dataset.geo;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * The city table <code>cities.tsv.gz</code>, read once on first use.
 *
 * <p>
 * One row per city with a population of at least 15000, the most populous first, with the columns
 * name, entity name of its first-level administrative division (the country if it has none), entity
 * name of its country, latitude and longitude in degrees and population.
 *
 * <p>
 * The table is generated by <code>matheclipse-dataset/tools/build_geo_data.py</code>; see
 * <code>NOTICE-geodata.txt</code> next to it for the sources and their licence.
 */
final class CityTable {

  static final String RESOURCE = "cities.tsv.gz";

  /** One city of the table. */
  static final class City {
    /** The name of the city, as it is written. */
    final String name;
    /** The entity forms of the name, the region and the country. */
    final String entityName;
    final String region;
    final String country;
    final double latitude;
    final double longitude;
    final long population;

    private City(String[] columns) {
      name = columns[0];
      entityName = entityForm(columns[0]);
      region = columns[1];
      country = columns[2];
      latitude = Double.parseDouble(columns[3]);
      longitude = Double.parseDouble(columns[4]);
      population = Long.parseLong(columns[5]);
    }
  }

  private static final class Holder {
    static final CityTable TABLE = load();
  }

  /** The cities, the most populous first. */
  final List<City> cities;

  /** The cities by their normalized names, in the order of {@link #cities}. */
  private final Map<String, List<City>> byName;

  /** The cities by their normalized country names, in the order of {@link #cities}. */
  private final Map<String, List<City>> byCountry;

  private CityTable(List<City> cities) {
    this.cities = Collections.unmodifiableList(cities);
    Map<String, List<City>> byName = new HashMap<String, List<City>>();
    Map<String, List<City>> byCountry = new HashMap<String, List<City>>();
    for (City city : cities) {
      byName.computeIfAbsent(CountryTable.key(city.name), k -> new ArrayList<City>()).add(city);
      byCountry.computeIfAbsent(CountryTable.key(city.country), k -> new ArrayList<City>())
          .add(city);
    }
    this.byName = byName;
    this.byCountry = byCountry;
  }

  static CityTable get() {
    return Holder.TABLE;
  }

  /** The cities of a name, the most populous first. */
  List<City> named(String name) {
    return byName.getOrDefault(CountryTable.key(name), Collections.emptyList());
  }

  /** The cities of a country given by its entity name, the most populous first. */
  List<City> inCountry(String country) {
    return byCountry.getOrDefault(CountryTable.key(country), Collections.emptyList());
  }

  /** The words of a name capitalized and joined, letters and digits only. */
  static String entityForm(String name) {
    StringBuilder buf = new StringBuilder(name.length());
    boolean wordStart = true;
    for (int i = 0; i < name.length(); i++) {
      char c = name.charAt(i);
      if (Character.isLetterOrDigit(c)) {
        buf.append(wordStart ? Character.toUpperCase(c) : c);
        wordStart = false;
      } else {
        wordStart = true;
      }
    }
    return buf.toString();
  }

  private static CityTable load() {
    List<City> cities = new ArrayList<City>();
    for (String[] row : CountryTable.readRows(RESOURCE)) {
      cities.add(new City(row));
    }
    return new CityTable(cities);
  }
}
